values.content:
=Analyze the following meeting transcript and provide:

1. A concise meeting summary (3-5 bullet points)
2. A list of action items with assignees (if mentioned) and due dates (if mentioned)
3. Key decisions made during the meeting

Format your response as JSON with this exact structure:
{
  "summary": ["bullet 1", "bullet 2", "bullet 3"],
  "actionItems": [
    {"task": "task description", "assignee": "name or 'Unassigned'", "dueDate": "date or 'TBD'"}
  ],
  "keyDecisions": ["decision 1", "decision 2"]
}

Meeting Transcript:
{{ $json.text }}

parameters.jsCode:
const transcript = $('Transcribe with Whisper').item.json.text || '';
const webhookData = $('Receive Meeting Recording').item.json.body;
const attendees = webhookData.attendees || [];
const meetingTitle = webhookData.meetingTitle || 'Meeting';
const meetingDate = webhookData.meetingDate || new Date().toISOString().split('T')[0];
let aiResponse;
try {
  const rawText = $input.item.json.content?.[0]?.text || $input.item.json.text || $input.item.json.output || '';
  aiResponse = JSON.parse(rawText);
} catch (e) {
  aiResponse = { summary: ['Meeting summary could not be parsed.'], actionItems: [], keyDecisions: [] };
}
const summaryBullets = (aiResponse.summary || []).map(b => '• ' + b).join('
');
const actionItemsList = (aiResponse.actionItems || []).map(a => '• ' + a.task + ' — Assignee: ' + a.assignee + ' | Due: ' + a.dueDate).join('
');
const decisionsList = (aiResponse.keyDecisions || []).map(d => '• ' + d).join('
');
const emailBody = '<h2>Meeting Summary: ' + meetingTitle + '</h2><p><strong>Date:</strong> ' + meetingDate + '</p><p><strong>Attendees:</strong> ' + attendees.join(', ') + '</p><h3>Summary</h3><p>' + summaryBullets.replace(/
/g, '<br>') + '</p><h3>Action Items</h3><p>' + (actionItemsList ? actionItemsList.replace(/
/g, '<br>') : 'No action items identified.') + '</p><h3>Key Decisions</h3><p>' + (decisionsList ? decisionsList.replace(/
/g, '<br>') : 'No key decisions recorded.') + '</p><hr><p style="color:#888;font-size:12px;">This summary was automatically generated from the meeting recording.</p>';
return { meetingTitle, meetingDate, attendees, attendeeList: attendees.join(', '), emailBody, summary: aiResponse.summary || [], actionItems: aiResponse.actionItems || [], keyDecisions: aiResponse.keyDecisions || [] };
